create or replace function public.retry_marketplace_checkout_session(p_reference text) returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$ declare v_id uuid; v_status text; begin if coalesce(auth.role(), '') <> 'service_role' then raise exception 'service role required' using errcode = '42501'; end if; select id, status into v_id, v_status from public.marketplace_checkout_sessions where reference = p_reference for update; if not found then return jsonb_build_object('status','unknown_reference'); end if; if v_status = 'paid' then return jsonb_build_object('status','paid','already',true); end if; if v_status <> 'fulfilment_error' then return jsonb_build_object('status',v_status,'retryable',false); end if; update public.marketplace_checkout_sessions set status='awaiting_payment', error=null, updated_at=now() where id=v_id; return jsonb_build_object('status','awaiting_payment','retryable',true); end; $$;
